import { useAudit } from "@/components/AuditLogViewer";

type StepStatus = "pending" | "in_progress" | "done" | "skipped";

interface PlaybookStep {
  id: string;
  title: string;
  description: string;
  assignee?: string;
  duration?: string;
  status: StepStatus;
  completedAt?: string;
}

interface ActivePlaybook {
  id: string;
  title: string;
  description: string;
  category: string;
  severity: string;
  status: string;
  steps: PlaybookStep[];
  created_at: string;
}

