const SEV_BADGE: Record<string, string> = {
  critical: "bg-destructive/15 text-destructive border-destructive/40",
  high:     "bg-orange-500/15 text-orange-400 border-orange-500/40",
  medium:   "bg-yellow-500/15 text-yellow-500 border-yellow-500/40",
};

const ICON_MAP: Record<string, React.ReactNode> = {
  lock:     <Lock     className="w-5 h-5 text-destructive" />,
  globe:    <Globe    className="w-5 h-5 text-blue-400" />,
  database: <Database className="w-5 h-5 text-orange-400" />,
  bug:      <Bug      className="w-5 h-5 text-purple-400" />,
};

const STEP_ICON: Record<StepStatus, React.ReactNode> = {
  pending:     <Circle      className="w-5 h-5 text-muted-foreground shrink-0" />,
  in_progress: <Clock       className="w-5 h-5 text-primary shrink-0 animate-pulse" />,
  done:        <CheckCircle2 className="w-5 h-5 text-green-500 shrink-0" />,
  skipped:     <span className="w-5 h-5 shrink-0 text-center text-muted-foreground text-xs flex items-center justify-center">–</span>,
};

function RunnerView({ pb, onUpdate, onClose }: {
  pb: ActivePlaybook;
  onUpdate: (pb: ActivePlaybook) => void;
  onClose: () => void;
}) {
  const audit = useAudit();
  const done = pb.steps.filter(s => s.status === "done" || s.status === "skipped").length;
  const pct  = pb.steps.length ? Math.round((done / pb.steps.length) * 100) : 0;

  const advance = (stepId: string, status: StepStatus) => {
    const step = pb.steps.find(s => s.id === stepId);
    const updated: ActivePlaybook = {
      ...pb,
      steps: pb.steps.map(s =>
        s.id === stepId
          ? { ...s, status, completedAt: status === "done" ? new Date().toISOString() : undefined }
          : s
      ),
    };
    onUpdate(updated);
    audit.log(status === "done" ? "playbook.step_complete" : "playbook.step_skip", "playbooks", pb.id, { stepId, stepTitle: step?.title });
  };

  return (
    <div>
      <div className="flex items-center gap-3 mb-4">
        <Button variant="ghost" size="sm" className="h-8 text-xs" onClick={onClose}>← Back</Button>
        <div className="flex-1">
          <h2 className="font-semibold">{pb.title}</h2>
          <p className="text-xs text-muted-foreground">{pb.description}</p>
        </div>
      </div>
      <div className="flex items-center gap-3 mb-4">
        <div className="flex-1">
          <div className="flex justify-between text-sm mb-1">
            <span>{done}/{pb.steps.length} complete</span>
            <span className="font-bold text-primary">{pct}%</span>
          </div>
          <div className="h-2 rounded-full bg-border/60 overflow-hidden">
            <div className="h-full rounded-full bg-primary transition-all" style={{ width: `${pct}%` }} />
          </div>
        </div>
      </div>
      <div className="space-y-2">
        {pb.steps.map((step, i) => (
          <div key={step.id} className={`rounded-xl border transition-all ${step.status === "done" ? "border-green-500/30 bg-green-500/5" : step.status === "in_progress" ? "border-primary/30 bg-primary/5" : "border-border/60 bg-card/60"}`}>
            <div className="flex items-start gap-3 p-4">
              {STEP_ICON[step.status]}
              <div className="flex-1 min-w-0">
                <div className="flex flex-wrap items-center gap-2 mb-1">
                  <span className="text-xs font-bold text-muted-foreground">Step {i + 1}</span>
                  {step.duration && <Badge variant="outline" className="text-[9px]">{step.duration}</Badge>}
                  {step.assignee && (
                    <span className="text-[10px] text-muted-foreground flex items-center gap-1">
                      <User className="w-3 h-3" />{step.assignee}
                    </span>
                  )}
                  {step.completedAt && (
                    <span className="text-[10px] text-green-500 ml-auto">
                      {new Date(step.completedAt).toLocaleTimeString()}
                    </span>
                  )}
                </div>
                <p className="font-medium text-sm mb-1">{step.title}</p>
                <p className="text-xs text-muted-foreground">{step.description}</p>
              </div>
              {step.status !== "done" && step.status !== "skipped" && (
                <div className="flex flex-col gap-1 ml-2 shrink-0">
                  <Button size="sm" className="h-7 text-xs" onClick={() => advance(step.id, "done")}>
                    <CheckCircle2 className="w-3 h-3 mr-1" />Done
                  </Button>
                  <Button size="sm" variant="ghost" className="h-7 text-xs text-muted-foreground" onClick={() => advance(step.id, "skipped")}>
                    Skip
                  </Button>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default function PlaybookManager() {
  const { toast } = useToast();
  const audit = useAudit();
  const [runs, setRuns]       = useState<ActivePlaybook[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<ActivePlaybook | null>(null);

  const loadRuns = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("playbooks")
      .select("*")
      .eq("status", "active")
      .order("created_at", { ascending: false });
    if (error) toast({ title: "Load failed", description: error.message, variant: "destructive" });
    else setRuns((data ?? []) as unknown as ActivePlaybook[]);
    setLoading(false);
  }, [toast]);

  useEffect(() => { loadRuns(); }, [loadRuns]);

  const activatePlaybook = async (tpl: typeof LIBRARY[0]) => {
    const row = {
      title:       tpl.title,
      description: tpl.description,
      category:    tpl.category,
      severity:    tpl.severity,
      status:      "active",
      steps:       tpl.steps.map(s => ({ ...s, status: "pending" as StepStatus })),
      tags:        [tpl.category],
    };
    const { data, error } = await supabase.from("playbooks").insert([row]).select().single();
    if (error) { toast({ title: "Activate failed", description: error.message, variant: "destructive" }); return; }
    const pb = data as unknown as ActivePlaybook;
    setRuns(prev => [pb, ...prev]);
    setSelected(pb);
    audit.log("playbook.activate", "playbooks", pb.id, { title: tpl.title, category: tpl.category, severity: tpl.severity });
    toast({ title: `Playbook activated: ${tpl.title}` });
  };

  const updatePlaybook = async (pb: ActivePlaybook) => {
    const { error } = await supabase
      .from("playbooks")
      .update({ steps: pb.steps as unknown as never[], updated_at: new Date().toISOString() })
      .eq("id", pb.id);
    if (error) { toast({ title: "Save failed", description: error.message, variant: "destructive" }); return; }
    setRuns(prev => prev.map(r => r.id === pb.id ? pb : r));
    setSelected(pb);
  };

  const removePlaybook = async (id: string) => {
    const { error } = await supabase.from("playbooks").update({ status: "closed" }).eq("id", id);
    if (error) { toast({ title: "Remove failed", description: error.message, variant: "destructive" }); return; }
    setRuns(prev => prev.filter(r => r.id !== id));
    if (selected?.id === id) setSelected(null);
    audit.log("playbook.close", "playbooks", id);
    toast({ title: "Playbook closed" });
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      <div className="mb-6 flex items-start justify-between">
        <div className="flex items-center gap-3">
          <BookOpen className="h-6 w-6 text-primary" />
          <div>
            <h1 className="text-3xl font-bold">Playbook Manager</h1>
            <p className="text-muted-foreground text-sm">Standardized IR procedures — activate to guide your team step-by-step.</p>
          </div>
        </div>
        <Button variant="outline" size="sm" onClick={loadRuns} disabled={loading}>
          <RefreshCw className={`w-4 h-4 mr-2 ${loading ? "animate-spin" : ""}`} />Refresh
        </Button>
      </div>

      <div className="grid lg:grid-cols-5 gap-6">
        {/* Library */}
        <div className="lg:col-span-2 space-y-3">
          <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3">Template Library</h2>
          {LIBRARY.map(tpl => (
            <Card key={tpl.id} className="border-border/60 bg-card/60 hover:border-primary/40 transition-all">
              <CardContent className="py-4 px-4">
                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-muted shrink-0">
                    {ICON_MAP[tpl.icon] || <Shield className="w-5 h-5 text-primary" />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-sm mb-1">{tpl.title}</p>
                    <div className="flex gap-1.5 mb-1.5 flex-wrap">
                      <Badge className={`border text-[9px] ${SEV_BADGE[tpl.severity] ?? ""}`}>{tpl.severity.toUpperCase()}</Badge>
                      <Badge variant="outline" className="text-[9px]">{tpl.category}</Badge>
                      <Badge variant="outline" className="text-[9px]">{tpl.steps.length} steps</Badge>
                    </div>
                    <p className="text-xs text-muted-foreground line-clamp-2">{tpl.description}</p>
                  </div>
                </div>
                <Button size="sm" className="w-full mt-3 h-8 gap-2 text-xs" onClick={() => activatePlaybook(tpl)}>
                  <Play className="w-3.5 h-3.5" />Activate
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Active runs + runner */}
        <div className="lg:col-span-3 space-y-4">
          {selected ? (
            <RunnerView pb={selected} onUpdate={updatePlaybook} onClose={() => setSelected(null)} />
          ) : loading ? (
            <div className="text-center py-16 text-muted-foreground text-sm">Loading active playbooks…</div>
          ) : runs.length === 0 ? (
            <div className="text-center py-16 border border-dashed border-border/60 rounded-xl text-muted-foreground">
              <BookOpen className="w-12 h-12 mx-auto mb-4 opacity-20" />
              <p className="text-sm">No active playbooks.</p>
              <p className="text-xs mt-1">Activate one from the library to start guiding your incident response.</p>
            </div>
          ) : (
            <>
              <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                Active Playbooks ({runs.length})
              </h2>
              {runs.map(pb => {
                const done = pb.steps.filter(s => s.status === "done" || s.status === "skipped").length;
                const pct  = Math.round((done / Math.max(pb.steps.length, 1)) * 100);
                return (
                  <Card key={pb.id} className="border-border/60 bg-card/60 cursor-pointer hover:border-primary/40 transition-all"
                    onClick={() => setSelected(pb)}>
                    <CardContent className="py-4 px-5">
                      <div className="flex items-center gap-3">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1 flex-wrap">
                            <span className="font-medium text-sm">{pb.title}</span>
                            <Badge className={`border text-[9px] ${SEV_BADGE[pb.severity] ?? ""}`}>{pb.severity?.toUpperCase()}</Badge>
                          </div>
                          <div className="flex items-center gap-2">
                            <div className="flex-1 h-1.5 rounded-full bg-border/60 overflow-hidden">
                              <div className="h-full rounded-full bg-primary" style={{ width: `${pct}%` }} />
                            </div>
                            <span className="text-xs text-muted-foreground shrink-0">{pct}%</span>
                          </div>
                        </div>
                        <div className="flex gap-1.5 shrink-0">
                          <Button size="sm" className="h-8 text-xs" onClick={e => { e.stopPropagation(); setSelected(pb); }}>
                            <ArrowRight className="w-3.5 h-3.5 mr-1" />Continue
                          </Button>
                          <Button size="sm" variant="ghost" className="h-8 w-8 p-0 text-muted-foreground hover:text-destructive"
                            onClick={e => { e.stopPropagation(); removePlaybook(pb.id); }}>
                            <Trash2 className="w-3.5 h-3.5" />
                          </Button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </>
          )}
        </div>
      </div>
    </div>
  );
}
